const io=new IntersectionObserver((es)=>{es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}})},{threshold:.12});
  document.querySelectorAll('.reveal').forEach(el=>io.observe(el));

  // ----- Carrusel reutilizable (manual, de a 3, loop) -----
  document.querySelectorAll('.carousel').forEach(function(root){
    const track=root.querySelector('.carousel-track');
    const dotsWrap=root.querySelector('.carousel-dots');
    if(!track) return;
    const originals=Array.from(track.children);
    const total=originals.length;
    const GAP=24;
    let head=[], tail=[], pos=0, n=3, animating=false;
    const perView=()=> window.matchMedia('(max-width:840px)').matches ? 1 : 3;

    function build(){
      head.forEach(c=>c.remove()); tail.forEach(c=>c.remove()); head=[]; tail=[];
      n=perView();
      for(let i=0;i<n;i++){const c=originals[i].cloneNode(true);c.setAttribute('aria-hidden','true');track.appendChild(c);tail.push(c);}
      for(let i=0;i<n;i++){const c=originals[total-1-i].cloneNode(true);c.setAttribute('aria-hidden','true');track.insertBefore(c,track.firstChild);head.push(c);}
      pos=n;
      render(false);
    }
    function stepPx(){return track.children[0].getBoundingClientRect().width+GAP;}
    function setDots(){
      if(!dotsWrap) return;
      const active=(((pos-n)%total)+total)%total;
      Array.from(dotsWrap.children).forEach((d,i)=>d.classList.toggle('active',i===active));
    }
    function render(anim){
      track.style.transition=anim?'transform .55s cubic-bezier(.5,.1,.2,1)':'none';
      track.style.transform='translateX('+(-pos*stepPx())+'px)';
      setDots();
    }
    function go(dir){
      if(animating) return; animating=true;
      pos+=dir; render(true);
      setTimeout(()=>{
        if(pos>=total+n){pos=n;render(false);}
        else if(pos<n){pos=pos+total;render(false);}
        animating=false;
      },570);
    }
    if(dotsWrap){
      for(let i=0;i<total;i++){
        const b=document.createElement('button');
        b.addEventListener('click',()=>{if(animating)return;pos=n+i;render(true);});
        dotsWrap.appendChild(b);
      }
    }
    root.querySelectorAll('.carousel-arrow').forEach(a=>{
      a.addEventListener('click',()=>go(parseInt(a.dataset.dir,10)));
    });

    build();
    let rt;
    window.addEventListener('resize',()=>{clearTimeout(rt);rt=setTimeout(build,200);});
  });
